-- Payments Operations SQL Analysis: schema (SQLite)
-- All data is synthetic and generated by seed.py. No real customer or platform data.
DROP TABLE IF EXISTS support_cases;
DROP TABLE IF EXISTS webhook_deliveries;
DROP TABLE IF EXISTS webhook_events;
DROP TABLE IF EXISTS webhook_endpoints;
DROP TABLE IF EXISTS charges;
DROP TABLE IF EXISTS merchants;

CREATE TABLE merchants (
  merchant_id INTEGER PRIMARY KEY,
  name        TEXT NOT NULL,
  segment     TEXT NOT NULL CHECK (segment IN ('enterprise','sme')),
  country     TEXT NOT NULL,
  created_at  TEXT NOT NULL
);

CREATE TABLE charges (
  charge_id      INTEGER PRIMARY KEY,
  merchant_id    INTEGER NOT NULL REFERENCES merchants(merchant_id),
  amount_cents   INTEGER NOT NULL,
  currency       TEXT NOT NULL,
  payment_method TEXT NOT NULL,
  status         TEXT NOT NULL CHECK (status IN ('succeeded','failed')),
  failure_code   TEXT,
  created_at     TEXT NOT NULL
);

CREATE TABLE webhook_endpoints (
  endpoint_id INTEGER PRIMARY KEY,
  merchant_id INTEGER NOT NULL REFERENCES merchants(merchant_id),
  url         TEXT NOT NULL
);

CREATE TABLE webhook_events (
  event_id    INTEGER PRIMARY KEY,
  endpoint_id INTEGER NOT NULL REFERENCES webhook_endpoints(endpoint_id),
  event_type  TEXT NOT NULL,
  created_at  TEXT NOT NULL
);

CREATE TABLE webhook_deliveries (
  delivery_id  INTEGER PRIMARY KEY,
  event_id     INTEGER NOT NULL REFERENCES webhook_events(event_id),
  attempt      INTEGER NOT NULL,
  http_status  INTEGER,            -- NULL = timeout / no response
  success      INTEGER NOT NULL CHECK (success IN (0,1)),
  attempted_at TEXT NOT NULL
);

CREATE TABLE support_cases (
  case_id     INTEGER PRIMARY KEY,
  merchant_id INTEGER NOT NULL REFERENCES merchants(merchant_id),
  category    TEXT NOT NULL,
  opened_at   TEXT NOT NULL,
  closed_at   TEXT,
  tier        INTEGER NOT NULL      -- 1, 2 or 3 (3 = highest escalation)
);

CREATE INDEX idx_charges_merchant ON charges(merchant_id, created_at);
CREATE INDEX idx_events_endpoint  ON webhook_events(endpoint_id);
CREATE INDEX idx_deliv_event      ON webhook_deliveries(event_id);
CREATE INDEX idx_cases_merchant   ON support_cases(merchant_id);
